&lt;p&gt;&lt;strong&gt;The Basics&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;We are&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;seeking&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;&amp;nbsp;a highly skilled&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;IT&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;Infrastructure Engineer&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;&amp;nbsp;with&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;expertise&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;&amp;nbsp;in&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;Systems Administration&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;to join the&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;IT Engineering&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;&amp;nbsp;team at Tanium. The ideal candidate will play a pivotal role in designing, implementing, and managing our&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;hybrid systems&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;&amp;nbsp;infrastructure to ensure&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;the availability, security, and maintenance of&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;our systems.&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW85415536 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;&lt;em&gt;This position follows the Company’s hybrid schedule which currently requires employees to work in the office at one of the following locations a minimum of &lt;span style=&quot;text-decoration: underline;&quot;&gt;three&lt;/span&gt; days per week: Addison, TX; Bellevue, WA; Durham, NC; Emeryville, CA; or Reston, VA.&lt;/em&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you&#39;ll do&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Embrace Tanium’s mission and core values.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:4,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Act as member of IT&amp;nbsp;Infrastructure Engineering team with a focus on systems management and project delivery&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Perform infrastructure deployment, management, planning, scaling, scheduling, etc.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Drive and enhance automation wherever possible in the name of efficiency, scalability, and consistency&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Work with a variety of key business groups to architect and implement technology and solutions&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Be accountable for ensuring all technology is documented,&amp;nbsp;deployed&amp;nbsp;and configured securely&amp;nbsp;and in alignment with best practices&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Leverage&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;AI and&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;automation tools&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;extensively&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;for&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;daily&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;tasks&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, integrations&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;and operation&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;and m&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;anagement of &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;IT&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;and business&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;services&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:4,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
