&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 10.0pt; font-family: &#39;Helvetica&#39;,sans-serif; color: black;&quot;&gt;Benefits and Perks include:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: start; word-spacing: 0px;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 10.0pt; font-family: &#39;Helvetica&#39;,sans-serif; color: black;&quot;&gt;· $500 Referral Bonus (receive bonus for referring family/friend CHHA)&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: start; word-spacing: 0px;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 10.0pt; font-family: &#39;Helvetica&#39;,sans-serif; color: black;&quot;&gt;· $2 /hr. extra pay for holidays&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: start; word-spacing: 0px;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 10.0pt; font-family: &#39;Helvetica&#39;,sans-serif; color: black;&quot;&gt;·&amp;nbsp;Vacation and Sick time&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 10.0pt; font-family: &#39;Helvetica&#39;,sans-serif; color: black;&quot;&gt;·&amp;nbsp;Flexible Schedule&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 10.0pt; font-family: &#39;Helvetica&#39;,sans-serif; color: black;&quot;&gt;·&amp;nbsp;We match caregivers with cases close to home&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: start; word-spacing: 0px;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 10.0pt; font-family: &#39;Helvetica&#39;,sans-serif; color: black;&quot;&gt;·&amp;nbsp;Direct Deposit&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: start; word-spacing: 0px;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 10.0pt; font-family: &#39;Helvetica&#39;,sans-serif; color: black;&quot;&gt;·&amp;nbsp;PPE provided&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
